import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D9E58p8B.js";const m=JSON.parse('{"title":"Quand ça ne marche pas","description":"","frontmatter":{"title":"Quand ça ne marche pas"},"headers":[],"relativePath":"agent/diagnostiquer.md","filePath":"agent/diagnostiquer.md"}'),r={name:"agent/diagnostiquer.md"};function d(s,e,i,u,c,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="quand-ca-ne-marche-pas" tabindex="-1">Quand ça ne marche pas <a class="header-anchor" href="#quand-ca-ne-marche-pas" aria-label="Permalink to &quot;Quand ça ne marche pas&quot;">​</a></h1><p>Avant de conclure qu&#39;un outil est en panne, l&#39;agent doit regarder l&#39;état de la machine : plusieurs défauts ne produisent aucune erreur.</p><h2 id="ce-que-vous-demandez" tabindex="-1">Ce que vous demandez <a class="header-anchor" href="#ce-que-vous-demandez" aria-label="Permalink to &quot;Ce que vous demandez&quot;">​</a></h2><blockquote><p>« Daimon ne semble rien faire : trouve pourquoi. »</p></blockquote><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><p>Il appelle <a href="/Daimon/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>, <strong>en premier</strong>. Un seul appel rend l&#39;état de chaque organe, sans jamais ouvrir de boîte de dialogue. Ce qu&#39;il lit :</p><table tabindex="0"><thead><tr><th>Clé</th><th>Ce qu&#39;elle apprend</th></tr></thead><tbody><tr><td><code>permissions</code></td><td>Quelle autorisation système manque</td></tr><tr><td><code>consequences</code></td><td>Ce que cette absence fait concrètement à chaque outil</td></tr><tr><td><code>ceiling</code></td><td>Le plafond actif</td></tr><tr><td><code>exclusions</code></td><td>L&#39;état de votre fichier d&#39;exclusions</td></tr><tr><td><code>overlay</code></td><td>Si le processus qui dessine les repères vit</td></tr><tr><td><code>cannot_detect</code></td><td>Ce que le diagnostic <strong>ne peut pas</strong> voir : une absence de problème n&#39;y est pas une preuve</td></tr><tr><td><code>next</code></td><td>Les prochaines étapes suggérées</td></tr></tbody></table><h2 id="les-symptomes-les-plus-courants" tabindex="-1">Les symptômes les plus courants <a class="header-anchor" href="#les-symptomes-les-plus-courants" aria-label="Permalink to &quot;Les symptômes les plus courants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptôme</th><th>Cause probable</th></tr></thead><tbody><tr><td>Une action répond <code>done</code> sans effet</td><td>Autorisation <strong>Accessibilité</strong> manquante</td></tr><tr><td>Une action attend 30 secondes</td><td>Autorisation <strong>Accessibilité</strong> manquante, ou confirmation en attente</td></tr><tr><td>Les captures échouent</td><td>Autorisation <strong>Enregistrement de l&#39;écran</strong> manquante</td></tr><tr><td>Une action est <code>refused</code></td><td>Au-dessus du plafond, ou confirmation non obtenue</td></tr><tr><td>Une capture est refusée ou noircie</td><td>Une application ou une zone de vos exclusions</td></tr><tr><td>Les repères n&#39;apparaissent pas</td><td><strong>Présence à l&#39;écran</strong> désactivée</td></tr><tr><td>L&#39;agent ne voit aucun outil Daimon</td><td>Daimon non enregistré dans cet agent, ou agent non redémarré</td></tr></tbody></table><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><p>Une cause nommée et la marche à suivre. Pour les causes qui dépendent de vos réglages, la page <a href="/Daimon/guide/depannage.html">Dépannage</a> donne le détail côté utilisateur.</p><h2 id="signaler-un-probleme" tabindex="-1">Signaler un problème <a class="header-anchor" href="#signaler-un-probleme" aria-label="Permalink to &quot;Signaler un problème&quot;">​</a></h2><p>Si <code>daimon_doctor</code> ne l&#39;explique pas, <a href="https://github.com/ArboRithm/Daimon/issues" target="_blank" rel="noreferrer">ouvrez une issue</a> avec sa sortie.</p>',13)])])}const h=t(r,[["render",d]]);export{m as __pageData,h as default};
